#include <bits/stdc++.h>

using namespace std;

using int64 = long long;

const int MAXN = 100000 + 10;
const int LIM = 2000000000;
const int MAXX = 500 + 10;
const int MAXY = 100000 + 10;

int L, R, K, prSize;
int cnt[MAXN], pr[MAXN];
uint16_t f[MAXX][MAXY];
bool composite[MAXN];

void Init() {
    for (int i = 2; 1LL * i * i < MAXN; ++i) {
        if (!composite[i]) {
            for (int j = 2 * i; j < MAXN; j += i)
                composite[j] = true;
        }
    }

    for (int i = 2; i < MAXN; ++i) {
        if (!composite[i])
            pr[prSize++] = i;
        cnt[i] = prSize;
    }

    for (int j = 0; j < MAXY; ++j)
        f[0][j] = static_cast<uint16_t>(j - j / pr[0]);

    for (int i = 1; i < MAXX; ++i) {
        for (int j = 0; j < MAXY; ++j) {
            f[i][j] = static_cast<uint16_t>(
                f[i - 1][j] - f[i - 1][j / pr[i]]
            );
        }
    }
}

bool isPrime(int n) {
    if (n < 2)
        return false;
    for (int i = 2; 1LL * i * i <= n; ++i) {
        if (n % i == 0)
            return false;
    }
    return true;
}

int64 Calc(int n, int64 m) {
    if (m == 0)
        return 0;
    if (n == 0)
        return m;
    if (pr[n - 1] >= m)
        return 1;
    if (n <= MAXX && m < MAXY)
        return f[n - 1][static_cast<int>(m)];

    return Calc(n - 1, m) - Calc(n - 1, m / pr[n - 1]);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    Init();
    cin >> L >> R >> K;

    if (!isPrime(K)) {
        cout << 0 << '\n';
    } else if (1LL * K * K > LIM) {
        cout << (L <= K && K <= R) << '\n';
    } else {
        --L;
        cout << Calc(cnt[K] - 1, R / K)
             - Calc(cnt[K] - 1, L / K) << '\n';
    }

    return 0;
}

