#include <bits/stdc++.h>
using namespace std;

constexpr int MAXN = 100000 + 10;
constexpr int LIM = 2000000000;
constexpr int TABLE_A = 100;
constexpr int TABLE_M = 100000 + 10;

int L, R, K, primeCount;
int cnt[MAXN], primes[MAXN];
bool composite[MAXN];

uint16_t phiTable[TABLE_A][TABLE_M];

void init() {
    for (int i = 2; 1LL * i * i < MAXN; ++i) {
        if (!composite[i]) {
            for (int j = i * i; j < MAXN; j += i)
                composite[j] = true;
        }
    }

    for (int i = 2; i < MAXN; ++i) {
        if (!composite[i])
            primes[primeCount++] = i;
        cnt[i] = primeCount;
    }

    for (int j = 0; j < TABLE_M; ++j)
        phiTable[1][j] = static_cast<uint16_t>(j - j / 2);

    for (int i = 2; i < TABLE_A; ++i) {
        for (int j = 0; j < TABLE_M; ++j) {
            phiTable[i][j] = static_cast<uint16_t>(
                phiTable[i - 1][j] -
                phiTable[i - 1][j / primes[i - 1]]
            );
        }
    }
}

bool isPrime(int n) {
    if (n < 2)
        return false;
    for (int i = 2; 1LL * i * i <= n; ++i) {
        if (n % i == 0)
            return false;
    }
    return true;
}

long long calc(int n, long long m) {
    if (m <= 0)
        return 0;
    if (n == 0)
        return m;
    if (primes[n - 1] >= m)
        return 1;
    if (n < TABLE_A && m < TABLE_M)
        return phiTable[n][static_cast<int>(m)];

    return calc(n - 1, m) -
           calc(n - 1, m / primes[n - 1]);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    init();
    cin >> L >> R >> K;

    if (!isPrime(K)) {
        cout << 0 << '\n';
    } else if (1LL * K * K > LIM) {
        cout << (L <= K && K <= R) << '\n';
    } else {
        --L;
        cout << calc(cnt[K] - 1, R / K) -
                calc(cnt[K] - 1, L / K) << '\n';
    }

    return 0;
}

